import {partyDelayOpinions} from './party-delay.js';
const delayEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const delayButton=(label,action,value,disabled=false)=>`<button data-action="${action}" data-value="${delayEsc(value)}" ${disabled?'disabled':''}>${label}</button>`;
export function partyDelayPanel(state){
 const r=state.survivalRun;if(!r||r.activeSortie)return '';const events=(r.parties?.delays??[]).filter(e=>e.status!=='resolved'),recent=(r.parties?.delays??[]).filter(e=>e.status==='resolved').slice(-2).reverse(),locked=r.status!=='active'||!!r.kit?.pending;
 if(!events.length&&!recent.length)return '';
 return `<section class="party-delay" aria-label="다른 파티의 귀환 연락"><h2>돌아오지 않은 무전</h2>${events.map(e=>`<article data-party-delay="${delayEsc(e.id)}"><span>출발 ${e.day}일차 · ${delayEsc(e.name)}</span><h3>${e.status==='backup'?'구조 파티가 이동 중이다':'예정된 귀환 시간이 지났다'}</h3><p>${delayEsc(e.location)} · ${e.members.length}명 고립</p><blockquote>${delayEsc(e.radio)}</blockquote><p>현장 인원: ${e.members.map(k=>{const m=r.members.find(m=>m.key===k);return delayEsc(m?.label??k)+' · 부상 '+(m?.injury??0)+' / 수분 '+(m?.hydration??0);}).join(' · ')}</p>${e.status==='pending'?`<div class="debate-opinions">${partyDelayOpinions(state,e).map(o=>`<article data-delay-opinion="${delayEsc(o.key)}" data-stance="${o.choice}"><strong>${delayEsc(o.name)}</strong><p>“${delayEsc(o.line)}”</p></article>`).join('')}</div><p>기다리면 다음 날 무전이 옵니다. 현장 식량·물이 줄며 두 번의 밤이 지나면 물자를 버리고 우회 귀환합니다. 우회하면 부상 +1·피로가 늘어요.</p><div class="debate-choices">${delayButton('직접 길을 열러 간다 · 여력 1','survivalPartyRescue',e.id,locked||r.actions<1)}${delayButton('한 번 더 연락을 기다린다','survivalPartyDelay',e.id+'|wait',locked||e.choices.some(c=>c.day===r.day&&c.choice==='wait'))}${delayButton('물자를 버리고 우회 복귀하라고 한다','survivalPartyDelay',e.id+'|recall',locked)}</div><p>직접 지원: 가방을 준비해 부상자를 4턴 동안 보호하면 기존 파티 전원이 복귀합니다. 구조를 중단하면 현장 요청은 남아요.</p><label>대신 보낼 파티<select id="delay-backup-${delayEsc(e.id)}"><option value="">대기 파티 선택</option>${r.parties.groups.filter(p=>!p.mission&&!p.members.includes('taei')).map(p=>`<option value="${delayEsc(p.id)}">${delayEsc(p.name)} · ${p.members.length}명</option>`).join('')}</select></label>${delayButton('선택한 파티를 구조 지원에 보낸다','survivalPartyDelay',e.id+'|backup',locked||r.actions<1)}<small>여력 1 · 구조팀 1인당 식량·물 1. 다음 밤에 판정: 구조팀이 고립 인원의 절반 이상이고 위협 90 미만이면 구조합니다. 여건이 부족하면 함께 우회 귀환해요.</small>`:'<p>구조팀도 파견 상태입니다. 다음 날 귀환 보고에서 결과를 확인할 수 있어요.</p>'}</article>`).join('')}${recent.map(e=>`<article class="party-delay-result" data-delay-result="${delayEsc(e.id)}"><h3>${delayEsc(e.name)} · 귀환 보고</h3><p>${delayEsc(e.result)}</p><p>${['direct','backup'].includes(e.method)?'구조받은 동료와 지원한 동료는 서로 도왔던 경험을 기억합니다. 이후 구조 의견과 동행 신뢰에 반영돼요.':'우회 귀환한 동료들이 거점으로 돌아왔어요. 치료와 휴식을 먼저 살펴보세요.'}</p></article>`).join('')}</section>`;
}
